import Link from 'next/link'
import { ArrowLeft, BookOpen, CheckCircle } from 'lucide-react'

const modules = [
  'Observation du texte biblique',
  'Interprétation et contexte',
  'Application personnelle et enseignement',
  'Étude des genres littéraires bibliques',
  'Méthode inductive en groupe',
  'Rédaction de notes et partage',
]

export default function BibleInductivePage() {
  return (
    <main className="bg-gradient-to-b from-background to-sky-50/30">
      <div className="max-w-6xl mx-auto px-3 sm:px-4 lg:px-6 py-3 sm:py-4 pb-6">
        <Link
          href="/ecoles"
          className="inline-flex items-center gap-1.5 text-xs sm:text-sm text-primary hover:text-primary/80 transition mb-3"
        >
          <ArrowLeft className="w-3.5 h-3.5 sm:w-4 sm:h-4 shrink-0" />
          Retour aux écoles
        </Link>

        <div className="text-center mb-4">
          <div className="space-y-2">
            <div className="flex flex-wrap items-center justify-center gap-1.5 sm:gap-2">
              <div className="text-xl sm:text-2xl leading-none" aria-hidden>
                📖
              </div>
              <span className="inline-flex items-center gap-1 bg-green-100 text-green-800 text-[10px] sm:text-xs font-medium px-2 py-0.5 rounded-full">
                <CheckCircle className="w-3 h-3 shrink-0" />
                Formation disponible
              </span>
            </div>
            <h1 className="text-xl sm:text-2xl md:text-3xl font-bold text-primary leading-tight">
              École Inductive de la Bible
            </h1>
            <p className="text-xs sm:text-sm text-foreground/80 leading-relaxed max-w-3xl mx-auto">
              Maîtrisez la méthode inductive pour une étude biblique profonde, personnelle et transmissible.
            </p>
            <Link
              href="/inscription"
              className="inline-flex items-center justify-center px-4 py-2 text-xs sm:text-sm bg-green-600 text-white rounded-md font-semibold hover:bg-green-700 transition"
            >
              S&apos;inscrire maintenant
            </Link>
          </div>
        </div>

        <div className="bg-white rounded-lg shadow-sm p-3 sm:p-4 border border-sky-100 mb-4">
          <h2 className="text-sm sm:text-base font-bold text-primary mb-2">À propos</h2>
          <p className="text-xs sm:text-sm text-foreground/70 leading-relaxed mb-3">
            Cette école forme à l&apos;étude rigoureuse des Écritures : observer le texte, comprendre son sens et
            l&apos;appliquer à la vie quotidienne et au service.
          </p>
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-2 sm:gap-2.5">
            {modules.map((module) => (
              <div
                key={module}
                className="border border-sky-500/20 rounded-md p-2.5 sm:p-3 bg-sky-500/5 flex items-start gap-2"
              >
                <BookOpen className="w-4 h-4 text-sky-600 shrink-0 mt-0.5" />
                <p className="text-xs sm:text-sm font-medium text-foreground/80">{module}</p>
              </div>
            ))}
          </div>
        </div>

        <div className="flex flex-col sm:flex-row gap-2 pt-1">
          <Link
            href="/inscription"
            className="px-4 py-2 text-xs sm:text-sm bg-green-600 text-white rounded-md font-semibold hover:bg-green-700 transition text-center"
          >
            S&apos;inscrire maintenant
          </Link>
          <Link
            href="/contact"
            className="px-4 py-2 text-xs sm:text-sm border border-primary text-primary rounded-md font-semibold hover:bg-primary/5 transition text-center"
          >
            Nous contacter
          </Link>
        </div>
      </div>
    </main>
  )
}
